package com.example.lending.domain;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

// 한 책의 예약 줄. 리스트 순서가 곧 줄 순서다 (먼저 건 예약이 앞에 온다)
public class ReservationQueue {

    private final List<Reservation> reservations;

    public ReservationQueue(List<Reservation> reservations) {
        this.reservations = new ArrayList<>(reservations);
    }

    public Reservation join(Reservation reservation) {
        UUID memberId = reservation.getMemberId();
        if (reservations.stream().anyMatch(r -> r.getMemberId().equals(memberId))) {
            throw new AlreadyReservedException(reservation.getBookId(), memberId);
        }
        reservations.add(reservation);
        return reservation;
    }

    // 1부터 시작하는 줄 순서. 줄에 없는 회원이면 예외다
    public int positionOf(UUID memberId) {
        for (int i = 0; i < reservations.size(); i++) {
            if (reservations.get(i).getMemberId().equals(memberId)) {
                return i + 1;
            }
        }
        throw new IllegalStateException("member is not in the reservation queue: " + memberId);
    }

    public Optional<Reservation> first() {
        return reservations.isEmpty() ? Optional.empty() : Optional.of(reservations.get(0));
    }

    // 예약이 없으면 누구나 빌릴 수 있고, 예약이 있으면 맨 앞 예약자만 빌릴 수 있다
    public boolean allowsLoanTo(UUID memberId) {
        return first().map(r -> r.getMemberId().equals(memberId)).orElse(true);
    }

    public List<Reservation> asList() {
        return List.copyOf(reservations);
    }
}
