package com.example.lending.application.service;

import com.example.lending.application.port.in.GetReservationsUseCase;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadReservationsPort;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Reservation;
import com.example.lending.domain.ReservationQueue;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.stream.IntStream;

@Service
@Transactional(readOnly = true)
public class GetReservationsService implements GetReservationsUseCase {

    private final LoadBookPort loadBookPort;
    private final LoadReservationsPort loadReservationsPort;

    public GetReservationsService(LoadBookPort loadBookPort, LoadReservationsPort loadReservationsPort) {
        this.loadBookPort = loadBookPort;
        this.loadReservationsPort = loadReservationsPort;
    }

    @Override
    public List<ReservationQueueItem> getReservations(GetReservationsQuery query) {
        loadBookPort.loadBook(query.bookId())
                .orElseThrow(() -> new BookNotFoundException(query.bookId()));

        List<Reservation> queue = new ReservationQueue(loadReservationsPort.loadReservations(query.bookId())).asList();
        return IntStream.range(0, queue.size())
                .mapToObj(i -> new ReservationQueueItem(queue.get(i).getId(), queue.get(i).getMemberId(), i + 1))
                .toList();
    }
}
