package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetReservationsUseCase;
import com.example.lending.application.port.in.GetReservationsUseCase.GetReservationsQuery;
import com.example.lending.application.port.in.GetReservationsUseCase.ReservationQueueItem;
import com.example.lending.application.port.in.ReserveBookUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.ReserveBookCommand;
import com.example.lending.application.port.in.ReserveBookUseCase.ReservationPlacement;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books/{bookId}/reservations")
public class ReservationController {

    private final ReserveBookUseCase reserveBookUseCase;
    private final GetReservationsUseCase getReservationsUseCase;

    public ReservationController(ReserveBookUseCase reserveBookUseCase,
                                 GetReservationsUseCase getReservationsUseCase) {
        this.reserveBookUseCase = reserveBookUseCase;
        this.getReservationsUseCase = getReservationsUseCase;
    }

    // 대출 중인 책에 줄을 선다. 대출 가능한 책에는 예약할 수 없다
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ReserveBookResponse reserveBook(@PathVariable UUID bookId, @RequestBody ReserveBookRequest request) {
        ReservationPlacement placement = reserveBookUseCase.reserveBook(
                new ReserveBookCommand(bookId, request.memberId()));
        return ReserveBookResponse.from(placement);
    }

    // 소진되지 않은 예약을 줄 순서대로 준다
    @GetMapping
    public List<ReservationItemResponse> getReservations(@PathVariable UUID bookId) {
        return getReservationsUseCase.getReservations(new GetReservationsQuery(bookId)).stream()
                .map(ReservationItemResponse::from)
                .toList();
    }
}
